n = int(input())
p = list(map(int, input().split()))

ans = 0
for k in range(n):
    happy = 0
    for i in range(n):
        if (p[i] == (i + k) % n or p[i] == (i + k - 1) % n or p[i] == (i + k + 1) % n):
            happy += 1
    ans = max(ans, happy)
print(ans)

